'use strict';

const { readArgs, ArgError } = require('./args');
const days = require('./days');
const { loadEntries, saveEntries } = require('./store');

function hours(n) {
  return `${Number(n.toFixed(2))}h`;
}

const commands = {
  add: {
    usage: 'add <hours> <project> [note] [--day YYYY-MM-DD]',
    run(argv, out) {
      const { words, opts } = readArgs(argv, { day: 'day' });
      const [h, project, ...note] = words;
      const value = Number(h);
      if (!(value > 0) || !project) throw new ArgError('usage: ' + commands.add.usage);
      const entries = loadEntries();
      const entry = { day: opts.day || days.today(), hours: value, project, note: note.join(' ') };
      entries.push(entry);
      saveEntries(entries);
      out(`Logged ${hours(value)} on ${project} for ${entry.day}`);
    },
  },

  list: {
    usage: 'list [--project NAME]',
    run(argv, out) {
      const { opts } = readArgs(argv, { project: 'text' });
      const entries = loadEntries().filter((e) => !opts.project || e.project === opts.project);
      entries.sort((a, b) => (a.day < b.day ? -1 : a.day > b.day ? 1 : 0));
      for (const e of entries) out(`${e.day}  ${hours(e.hours).padStart(6)}  ${e.project}${e.note ? '  ' + e.note : ''}`);
      if (entries.length === 0) out('No entries.');
    },
  },

  total: {
    usage: 'total [--project NAME]',
    run(argv, out) {
      const { opts } = readArgs(argv, { project: 'text' });
      const entries = loadEntries().filter((e) => !opts.project || e.project === opts.project);
      const perProject = new Map();
      for (const e of entries) perProject.set(e.project, (perProject.get(e.project) || 0) + e.hours);
      for (const [project, sum] of [...perProject].sort()) out(`${project.padEnd(12)} ${hours(sum)}`);
      out(`${'Total'.padEnd(12)} ${hours(entries.reduce((s, e) => s + e.hours, 0))}`);
    },
  },
};

function main(argv, out = console.log) {
  const [name, ...rest] = argv;
  const command = commands[name];
  if (!command) {
    out('usage: worklog <command>\n' + Object.values(commands).map((c) => '  ' + c.usage).join('\n'));
    return name ? 1 : 0;
  }
  try {
    command.run(rest, out);
    return 0;
  } catch (err) {
    if (err instanceof ArgError) {
      out(`worklog ${name}: ${err.message}`);
      return 1;
    }
    throw err;
  }
}

module.exports = { commands, main };
'use strict';

// Days are plain strings, 'YYYY-MM-DD', in local time. Keeping them as strings means they sort and
// compare correctly as text and survive the round trip through worklog.json unchanged.

const DAY = /^(\d{4})-(\d{2})-(\d{2})$/;

function isDay(value) {
  if (typeof value !== 'string') return false;
  const m = DAY.exec(value);
  if (!m) return false;
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return d.getFullYear() === Number(m[1]) && d.getMonth() === Number(m[2]) - 1 && d.getDate() === Number(m[3]);
}

function toDate(day) {
  if (!isDay(day)) throw new Error(`not a day: ${day}`);
  const [y, m, d] = day.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function fromDate(date) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function today(now = new Date()) {
  return fromDate(now);
}

// shift('2026-11-30', 1) === '2026-12-01'; negative counts go back.
function shift(day, count) {
  const d = toDate(day);
  d.setDate(d.getDate() + count);
  return fromDate(d);
}

// 1 = Monday ... 7 = Sunday (ISO numbering).
function weekday(day) {
  return toDate(day).getDay() || 7;
}

// The Monday of the week the day falls in.
function mondayOf(day) {
  return shift(day, 1 - weekday(day));
}

// Inclusive on both ends: inRange('2026-11-03', '2026-11-01', '2026-11-03') === true.
function inRange(day, first, last) {
  return day >= first && day <= last;
}

module.exports = { isDay, toDate, fromDate, today, shift, weekday, mondayOf, inRange };
'use strict';

// A small argument reader for the CLI. Each command declares the options it takes:
//
//   readArgs(['acme', '--day', '2026-11-03'], { day: 'day', verbose: 'switch' })
//   -> { words: ['acme'], opts: { day: '2026-11-03', verbose: false } }
//
// Option kinds: 'text' (takes a value), 'day' (takes a YYYY-MM-DD value), 'switch' (no value; true when
// present, false otherwise). An option the command doesn't declare is an error, so typos don't pass
// silently.

const { isDay } = require('./days');

class ArgError extends Error {}

function readArgs(argv, options = {}) {
  const words = [];
  const opts = {};
  for (const [name, kind] of Object.entries(options)) {
    if (kind === 'switch') opts[name] = false;
  }
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (!arg.startsWith('--')) {
      words.push(arg);
      continue;
    }
    const name = arg.slice(2);
    const kind = options[name];
    if (!kind) throw new ArgError(`unknown option --${name}`);
    if (kind === 'switch') {
      opts[name] = true;
      continue;
    }
    const value = argv[++i];
    if (value === undefined) throw new ArgError(`--${name} needs a value`);
    if (kind === 'day' && !isDay(value)) throw new ArgError(`--${name} must be a day (YYYY-MM-DD), not ${value}`);
    opts[name] = value;
  }
  return { words, opts };
}

module.exports = { readArgs, ArgError };
