{
  "name": "worklog",
  "version": "0.4.0",
  "description": "Log hours per project from the command line",
  "private": true,
  "bin": { "worklog": "bin/worklog.js" },
  "scripts": {
    "test": "node --test"
  }
}
'use strict';

const test = require('node:test');
const assert = require('node:assert');
const days = require('../lib/days');

test('recognises valid days only', () => {
  assert.ok(days.isDay('2026-02-28'));
  assert.ok(!days.isDay('2026-02-30'));
  assert.ok(!days.isDay('26-2-28'));
});

test('shift crosses month and year ends', () => {
  assert.strictEqual(days.shift('2026-11-30', 1), '2026-12-01');
  assert.strictEqual(days.shift('2026-01-01', -1), '2025-12-31');
});

test('weekday uses 1 for Monday and 7 for Sunday', () => {
  assert.strictEqual(days.weekday('2026-11-09'), 1);
  assert.strictEqual(days.weekday('2026-11-15'), 7);
});
'use strict';

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { main } = require('../lib/commands');
const { readArgs } = require('../lib/args');

function withLog(entries) {
  const file = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'worklog-')), 'worklog.json');
  fs.writeFileSync(file, JSON.stringify({ version: 1, entries }));
  process.env.WORKLOG_FILE = file;
  return file;
}

function run(argv) {
  const lines = [];
  const code = main(argv, (line) => lines.push(line));
  return { code, lines };
}

test('total adds up hours per project', () => {
  withLog([
    { day: '2026-11-02', hours: 2, project: 'acme', note: '' },
    { day: '2026-11-03', hours: 1.5, project: 'internal', note: '' },
    { day: '2026-11-04', hours: 3, project: 'acme', note: 'review' },
  ]);
  const { code, lines } = run(['total']);
  assert.strictEqual(code, 0);
  assert.deepStrictEqual(lines, ['acme         5h', 'internal     1.5h', 'Total        6.5h']);
});

test('total --project keeps one project', () => {
  withLog([
    { day: '2026-11-02', hours: 2, project: 'acme', note: '' },
    { day: '2026-11-03', hours: 1.5, project: 'internal', note: '' },
  ]);
  assert.deepStrictEqual(run(['total', '--project', 'internal']).lines, ['internal     1.5h', 'Total        1.5h']);
# worklog

Log hours per project from the command line. Entries are kept in `worklog.json` in the current folder
(or the file named by `WORKLOG_FILE`).

```
node bin/worklog.js add 2.5 acme "API review"
node bin/worklog.js add 1 internal --day 2026-11-03
node bin/worklog.js list --project acme
node bin/worklog.js total
node bin/worklog.js total --project acme
```

Tests: `npm test` (or `node --test`).

